**简单理解：装饰器是一种特殊的函数，它的形参是函数。**

# 无参装饰器

## 非语法糖写法
```python
import time

def count_time(func):
    def wrapper():
        t1 = time.time()
        func()
        print("执行时间为：", time.time() - t1)

    return wrapper

def baiyu():
    print("我是攻城狮白玉")
    time.sleep(2)


if __name__ == '__main__':
    baiyu = count_time(baiyu)  
    baiyu()  
```

## 语法糖写法
```python
import time

def count_time(func):
    def wrapper():
        t1 = time.time()
        func()
        print("执行时间为：", time.time() - t1)

    return wrapper

@count_time
def baiyu():
    print("我是攻城狮白玉")
    time.sleep(2)



if __name__ == '__main__':
    baiyu()  
```
# 带参装饰器

## 非语法糖写法


```python
import time
def count_time_args(msg=None):
    def count_time(func):
        def wrapper(*args, **kwargs):
            print("开始统计时间")
            t1 = time.time()
            func(*args, **kwargs)
            print(msg)
            print(f"执行时间为：", time.time() - t1)
        return wrapper
    return count_time

def fun_():
    print("fun_执行")
    time.sleep(1)

if __name__ == '__main__':
    temp_wrapper = count_time_args(msg="装饰器传参")
    new_fun = temp_wrapper(fun_)
    new_fun()

```
## 语法糖写法


```python
import time

def count_time_args(msg=None):
    def count_time(func):
        def wrapper(*args, **kwargs):
            print("开始统计时间")
            t1 = time.time()
            func(*args, **kwargs)
            print(msg)
            print(f"执行时间为：", time.time() - t1)
        return wrapper
    return count_time

@count_time_args(msg="装饰器传参")
def fun_():
    print("fun_执行")
    time.sleep(1)

if __name__ == '__main__':
	fun_()

```
